// The first beat in each 16-beat phrase is the bounded mesh clock correction point.
constexpr bool isTubesMeasureDownbeat(uint32_t beatFrame) {
  return ((beatFrame >> TUBES_BEAT_FRAME_FRACTION_SHIFT) & 0x0F) == 0;
}

// Every pole invokes `pickDelay` and retains the resulting speculative schedule.
// Channel authority decides only whether that local schedule may be published.
template<typename DelayPicker>
bool scheduleSpeculativeChannelChange(
    uint16_t currentPhrase,
    uint16_t& effectivePhrase,
    bool mayPublish,
    DelayPicker pickDelay
) {
  effectivePhrase = currentPhrase + pickDelay();
  return mayPublish;
}

